    const time = this.element.querySelector("time[datetime]")
    return time ? formatLocalTime(time) : this.bridgeElement.bridgeAttribute("description")
  }

  #observeStamp() {
    this.stampObserver = new MutationObserver(() => {
      this.notifyBridgeOfConnect()
    })

    this.stampObserver.observe(this.element, {
      attributes: true
    })
  }
}
